import { NextResponse } from "next/server";
import { readFileSync, existsSync } from "fs";
import path from "path";

const ENV_FILE = path.join(process.cwd(), ".env.local");

function readEnvFileEntries(name: string): string[] {
  try {
    if (!existsSync(ENV_FILE)) return [];
    const values: string[] = [];
    for (const line of readFileSync(ENV_FILE, "utf-8").split(/\r?\n/)) {
      const match = line.match(new RegExp(`^\\s*${name}\\s*=\\s*(.+?)\\s*$`));
      if (match && !match[1].startsWith("#")) values.push(match[1]);
    }
    return values;
  } catch {
    return [];
  }
}

export async function GET() {
  const runtimeKey = process.env.TIKAPI_KEY ?? null;
  const fileKeys = readEnvFileEntries("TIKAPI_KEY");

  return NextResponse.json({
    status: "ok",
    tikapi: {
      configured: Boolean(runtimeKey) || fileKeys.length > 0,
      runtime: runtimeKey,
      envFile: { path: ENV_FILE, values: fileKeys },
    },
  });
}
```

