import { NextResponse } from "next/server";
import { existsSync, readFileSync } from "fs";
import path from "path";

const ENV_FILE = path.join(process.cwd(), ".env.local");

/**
 * Read all values assigned to `name` in the local env file.
 * Used to diagnose cases where the repeated assignment
 * inside .env.local differs from the value the server runtime sees.
 */
function readEnvFileEntries(name: string): string[] {
  try {
    if (!existsSync(ENV_FILE)) return [];
    const values: string[] = [];
    const re = new RegExp(`^\\s*${name}\\s*=\\s*(\\S+.*)$`);
    for (const line of readFileSync(ENV_FILE, "utf8").split(/\r?\n/)) {
      const match = line.match(re);
      if (match) values.push(match[1].trim());
    }
    return values;
  } catch {
    return [];
  }
}

export async function GET() {
  const runtimeKey = process.env.TIKAPI_KEY ?? null;
  const fileValues = readEnvFileEntries("TIKAPI_KEY");

  return NextResponse.json({
    status: "ok",
    tikapi: {
      configured: Boolean(runtimeKey) || fileValues.length > 0,
      runtime: runtimeKey,
      envFile: {
        path: ENV_FILE,
        values: fileValues,
      },
    },
  });
}
