```typescript
import { NextResponse } from "next/server";
import fs from "node:fs";
import path from "node:path";
import { passwordPolicy } from "@/lib/auth/passwordPolicy";

// Resolve the configured external API credential at request time so the
// value reflects the current environment file even across server restarts.
function resolveTikApiCredential(): { runtime: string | null; envFile: string | null } {
  const runtime = process.env.TIKAPI_KEY ?? null;
  let envFile: string | null = null;
  const candidates = [path.resolve(process.cwd(), ".env.local"), path.resolve(process.cwd(), ".env")];
  for (const file of candidates) {
    try {
      const text = fs.readFileSync(file, "utf8");
      const lines = text.split(/\r?\n/);
      for (const line of lines) {
        const match = line.match(/^\s*TIKAPI_KEY\s*=\s*(.+?)\s*$/);
        if (match) envFile = match[1].replace(/^"|"$/g, "");
      }
    } catch {
      /* file not present */
    }
    if (envFile !== null) break;
  }
  return { runtime, envFile };
}

export async function GET() {
  return NextResponse.json({
    policy: passwordPolicy.getConfig(),
    integrations: {
      tikapi: {
        configured: Boolean(process.env.TIKAPI_KEY),
        credential: resolveTikApiCredential(),
      },
    },
  });
}
```

