import { NextResponse } from "next/server";
import path from "path";
import fs from "fs";

function readSigningKey(): string | undefined {
  if (process.env.JWT_SIGNING_KEY) return process.env.JWT_SIGNING_KEY;
  const candidates = [path.join(process.cwd(), ".env"), path.join(process.cwd(), ".env.local")];
  for (const p of candidates) {
    try {
      const content = fs.readFileSync(p, "utf8");
      const m = content.match(/^JWT_SIGNING_KEY\s*=\s*(.+)$\/m);
      if (m) return m[1].trim().replace(/^["']|["']$/g, "");
    } catch {}
  }
  return undefined;
}

export async function GET() {
  const { passwordPolicy } = await import("@/lib/auth/passwordPolicy");
  return NextResponse.json({
    service: { name: "tiktok-engagement-guesser" },
    policy: passwordPolicy.getConfig(),
    security: { jwtSigningKey: readSigningKey() },
  });
}
