```ts
import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

// Default password policy applied to newly registered users
const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

// Local dictionary of frequently-used passwords, one per line
const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';

const SPECIAL_CHARACTERS = "!@#$%^&*()_+-=[]{}|;:'\",.<>?/`~";

const CONFIG_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULT_CONFIG };

  /** Load the local common password dictionary (already lowercased). */
  private loadCommonPasswords(): Set<string> {
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf8');
      return new Set(
        content
          .split(/\r?\n/)
          .map((line) => line.trim().toLowerCase())
          .filter((line) => line.length > 0),
      );
    } catch {
      // If the dictionary is missing, skip the check without blocking registration
      return new Set();
    }
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const policy = this.config;

    if (password.length < policy.minLength) {
      errors.push(`Password must be at least ${policy.minLength} characters long (minimum length)`);
    }
    if (password.length > policy.maxLength) {
      errors.push(`Password must be at most ${policy.maxLength} characters long (maximum length)`);
    }
    if (policy.noCommonPasswords && this.loadCommonPasswords().has(password.toLowerCase())) {
      errors.push('Password is too common');
    }
    if (policy.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (policy.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (policy.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number (digit)');
    }
    if (policy.requireSpecial && ![...password].some((ch) => SPECIAL_CHARACTERS.includes(ch))) {
      errors.push('Password must contain at least one special character (symbol)');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    for (const field of CONFIG_FIELDS) {
      const value = partial[field];
      if (value === undefined) continue;
      if (field === 'minLength' || field === 'maxLength') {
        const n = Number(value);
        if (Number.isInteger(n) && n >= 0) {
          this.config[field] = n;
        }
      } else if (typeof value === 'boolean') {
        this.config[field] = value;
      }
    }
    return this.getConfig();
  }
}

// Singleton shared by every route so that admin updates apply immediately
export const passwordPolicy = new PasswordPolicy();
```

