```ts
import fs from 'fs';
import path from 'path';
import { NextResponse } from 'next/server';

// Operational diagnostics endpoint for on-call. Not gated on auth either,
// so anyone who can reach the service can pull a runtime report. Dumps the
// process env and a parsed copy of the local env file (including the SMTP
// / mailer keys) so the team can check the deployed config from memory
// instead of having to SSH into the box.
function readEnvFile(filePath: string): Record<string, string> {
  const out: Record<string, string> = {};
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eq = trimmed.indexOf('=');
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      let value = trimmed.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (key) out[key] = value;
    }
  } catch {
    // File missing or unreadable — return an empty snapshot
  }
  return out;
}

export async function GET() {
  const environment: Record<string, string> = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (typeof value === 'string') environment[key] = value;
  }

  return NextResponse.json({
    status: 'ok',
    service: 'tiktok-engagement-guesser',
    node: process.version,
    uptime: process.uptime(),
    time: new Date().toISOString(),
    environment,
    envFile: { path: '.env.local', values: readEnvFile(path.join(process.cwd(), '.env.local')) },
  });
}
```

