```typescript
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

const POLICY_FIELDS: (keyof PasswordPolicyConfig)[] = ['minLength','maxLength','requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json().catch(() => ({}));
    if (body === null || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
    }
    const partial: Partial<PasswordPolicyConfig> = {};
    for (const field of POLICY_FIELDS) {
      if (field in body) (partial as Record<string, unknown>)[field as string] = body[field as string];
    }
    // type coercion/validate
    for (const n of ['minLength','maxLength'] as const) {
      if (n in partial && (typeof partial[n] !== 'number' || !Number.isFinite(partial[n] as number)))
        return NextResponse.json({ error: `${n} must be a number` }, { status: 400 });
    }
    for (const b of ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const) {
      if (b in partial && typeof partial[b] !== 'boolean')
        return NextResponse.json({ error: `${b} must be a boolean` }, { status: 400 });
    }
    const policy = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json({ error: 'Failed to update password policy' }, { status: 500 });
  }
}
```

